using System;using System.IO;using System.Diagnostics;using Unity.VectorGraphics;using System.Linq;using System.Text.Json;using System.Collections.Generic;
class Program {static void Main(string[] paths){var results=new List<object>();float[] steps={1.5f,2,4,6,8},cord={.2f,.3f,.4f,.5f,.6f},angle={.2f,.25f,.3f,.4f,.5f},sample={.04f,.05f,.06f,.07f,.08f};foreach(var path in paths){using var reader=new StringReader(File.ReadAllText(path));var scene=SVGParser.ImportSVG(reader,(ViewportOptions)2,96f,1f,0,0);for(int i=0;i<5;i++){var sw=Stopwatch.StartNew();var opts=new VectorUtils.TessellationOptions{StepDistance=steps[i],MaxCordDeviation=cord[i],MaxTanAngleDeviation=angle[i],SamplingStepSize=sample[i]};var geometry=VectorUtils.TessellateScene(scene.Scene,opts,scene.NodeOpacity);int vertices=geometry.Sum(g=>g.Vertices.Length);results.Add(new{path,preset=i,milliseconds=sw.ElapsedMilliseconds,geometries=geometry.Count,vertices,indices=geometry.Sum(g=>g.Indices.Length),withinBudget=vertices<=65500});}}Console.WriteLine(JsonSerializer.Serialize(results,new JsonSerializerOptions{WriteIndented=true}));}}
